133	// Corner quoins: corner cell [x,z], and the neighbour cells along each exposed face [x, z, face].
134	const QUOINS = [
135	  { c: [1, 7], n: [[2, 7, "north"], [1, 8, "west"]] },
136	  { c: [17, 7], n: [[16, 7, "north"], [17, 8, "east"]] },
137	  { c: [18, 11], n: [[19, 11, "north"]] },
138	  { c: [1, 24], n: [[2, 24, "south"], [1, 23, "west"]] },
139	  { c: [17, 24], n: [[16, 24, "south"]] },
140	  { c: [18, 25], n: [[19, 25, "south"]] },
141	  { c: [35, 25], n: [[34, 25, "south"]] },
142	  { c: [42, 24], n: [[41, 24, "south"], [42, 23, "east"]] },
143	];
144	
145	const leaves = (name, extra = {}) => [name, { persistent: "true", ...extra }];
146	const hash = (x, y, z) => ((x * 73856093) ^ (y * 19349663) ^ (z * 83492791)) >>> 0;
147	const put = (g, [x, y, z], pair) => g.set(x, y, z, ...pair);
148	const mulchAt = (g, x, z) => { if (g.blockAt(x, 0, z) === "minecraft:grass_block") g.set(x, 0, z, MULCH); };
149	
150	// ---- wallBlock(face, x, y, z): pure; the [block, state] pair for one exterior wall cell -------------------------------
151	// y0 plinth; y5 and y9 belt and frieze; y1..4 veneer on the north (front) plane, which the caller also passes for the
152	// corner wrap cells; siding everywhere else.
153	export function wallBlock(face, x, y, z) {
154	  if (y === 0) return [PLINTH];
155	  if (y === 5 || y === 9) return [BELT];
156	  if (face === "north" && y >= 1 && y <= 4) return [veneerAt(x, y, z)];
157	  return [SIDING];
158	}
159	function veneerAt(x, y, z) {
160	  let r = hash(x, y, z) % 100;
161	  for (const [block, w] of VENEER_MIX) { if (r < w) return block; r -= w; }
162	  return VENEER_MIX[0][0];
163	}
164	
165	// ---- quoins(g): corner columns y1..9, neighbour cells alternate quartz (even y) and siding (odd y) -----------------
166	// y5 and y9 are the bands and are skipped on the neighbours. Lower-front veneer (north, y1..4) is kept.
167	export function quoins(g) {
168	  for (const { c: [cx, cz], n } of QUOINS) {
169	    for (let y = 1; y <= 9; y++) g.set(cx, y, cz, TRIM);
170	    for (const [nx, nz, f] of n) {
171	      for (let y = 1; y <= 9; y++) {
172	        if (y === 5 || y === 9) continue;
173	        if (f === "north" && y <= 4) continue;
174	        g.set(nx, y, nz, y % 2 === 0 ? TRIM : SIDING);
175	      }
176	    }
177	  }
178	}
179	
180	// ---- shutterCells(g): black strips beside every sh window, over its y range ----------------------------------------
181	export function shutterCells(g) {
182	  for (const o of OPENINGS) {
183	    if (!o.sh) continue;
184	    for (let y = o.y[0]; y <= o.y[1]; y++) {
185	      if (o.face === "north" || o.face === "south") {
186	        g.set(o.x[0] - 1, y, o.z[0], SHUTTER);
187	        g.set(o.x[1] + 1, y, o.z[0], SHUTTER);
188	      } else {
189	        g.set(o.x[0], y, o.z[0] - 1, SHUTTER);
190	        g.set(o.x[0], y, o.z[1] + 1, SHUTTER);
191	      }
192	    }
193	  }
194	}
195	
196	// ---- archWindow(g, a0, a1, yb, yt, plane, face): glass, arch springers, sill and hood ----------------------------
197	// For north/south faces the window runs along x (a0..a1 are x) at z = plane; for east/west it runs along z at x = plane.
198	// Springers face away from the window centre (west/east, or north/south on the x faces). Sill and hood sit on the
199	// outside plane (plane-1 for north and west, plane+1 for south and east).
200	export function archWindow(g, a0, a1, yb, yt, plane, face) {
201	  const alongX = face === "north" || face === "south";
202	  const at = (a, y, p) => (alongX ? [a, y, p] : [p, y, a]);
203	  const outside = face === "north" || face === "west" ? plane - 1 : plane + 1;
204	  const low = alongX ? "west" : "north", high = alongX ? "east" : "south";
205	  for (let a = a0; a <= a1; a++) for (let y = yb; y <= yt; y++) put(g, at(a, y, plane), [GLASS]);
206	  if (a0 === a1) put(g, at(a0, yt, plane), B.slab("quartz", "top"));
207	  else { put(g, at(a0, yt, plane), B.stairs("quartz", low, "top")); put(g, at(a1, yt, plane), B.stairs("quartz", high, "top")); }
208	  for (let a = a0; a <= a1; a++) {
209	    put(g, at(a, yb - 1, outside), B.slab("quartz", "top"));
210	    put(g, at(a, yt + 1, outside), B.slab("quartz", "bottom"));
211	  }
212	}
213	
214	// archOpening(g, o): archWindow for an OPENINGS entry (face and ranges taken from the entry).
215	export function archOpening(g, o) {
216	  const alongX = o.face === "north" || o.face === "south";
217	  if (alongX) archWindow(g, o.x[0], o.x[1], o.y[0], o.y[1], o.z[0], o.face);
218	  else archWindow(g, o.z[0], o.z[1], o.y[0], o.y[1], o.x[0], o.face);
219	}
220	
221	// ---- entryDoor(g, o): the 4-wide entry or back door at an OPENINGS entry (kind entry) ---------------------------
222	// Doors dark_oak_door at the two middle columns (hinges on the outer ends), sidelights, transom, fan and springers.
223	// The palladian window above is its own OPENINGS entry (kind palladian): archOpening.
224	export function entryDoor(g, o) {
225	  const [x0, x1] = o.x, [y0] = o.y, z = o.z[0], facing = o.face;
226	  const midLeft = x0 + 1, midRight = x0 + 2;
227	  for (const [x, hinge] of [[midLeft, "left"], [midRight, "right"]]) {
228	    g.set(x, y0, z, ...B.door("dark_oak", facing, "lower", hinge));
229	    g.set(x, y0 + 1, z, ...B.door("dark_oak", facing, "upper", hinge));
230	  }
231	  for (let y = y0; y <= y0 + 2; y++) { g.set(x0, y, z, GLASS); g.set(x1, y, z, GLASS); }
232	  g.set(midLeft, y0 + 2, z, GLASS); g.set(midRight, y0 + 2, z, GLASS);
233	  g.set(midLeft, y0 + 3, z, GLASS); g.set(midRight, y0 + 3, z, GLASS);
234	  put(g, [x0, y0 + 3, z], B.stairs("quartz", "west", "top"));
235	  put(g, [x1, y0 + 3, z], B.stairs("quartz", "east", "top"));
236	}
237	
238	// plainDoor(g, o): a one-wide 2-high door (the garage back door) at an OPENINGS entry.
239	export function plainDoor(g, o) {
240	  g.set(o.x[0], o.y[0], o.z[0], ...B.door("dark_oak", o.face, "lower", "left"));
241	  g.set(o.x[0], o.y[0] + 1, o.z[0], ...B.door("dark_oak", o.face, "upper", "left"));
242	}
243	
244	// ---- column(g, x, z): quartz base, shaft, chiseled capital (y1..8) -------------------------------------------------
245	export function column(g, x, z) {
246	  g.set(x, 1, z, ...B.slab("quartz", "bottom"));
247	  for (let y = 2; y <= 7; y++) g.set(x, y, z, ...B.pillar("quartz_pillar", "y"));
248	  g.set(x, 8, z, "chiseled_quartz_block");
249	}
250	
251	// ---- portico(g): floor, four columns, half columns at the wall, entablature, ceiling, landing, hanging lanterns ----
252	export function portico(g) {
253	  g.fill([22, 0, 7], [31, 0, 10], "stone_bricks");
254	  g.fill([26, 0, 7], [27, 0, 10], BELT);
255	  for (const x of [23, 25, 28, 30]) column(g, x, 7);
256	  for (const x of [23, 30]) for (let y = 1; y <= 8; y++) g.set(x, y, 10, ...B.pillar("quartz_pillar", "y"));
257	  g.fill([22, 9, 7], [31, 9, 7], "quartz_block");
258	  g.fill([22, 9, 7], [22, 9, 10], "quartz_block");
259	  g.fill([31, 9, 7], [31, 9, 10], "quartz_block");
260	  g.fill([23, 9, 8], [30, 9, 10], SIDING);
261	  for (let x = 24; x <= 29; x++) put(g, [x, 1, 6], B.slab("stone_brick", "bottom"));
262	  g.set(26, 8, 8, ...B.lantern(true));
263	  g.set(27, 8, 8, ...B.lantern(true));
264	}
265	
266	// ---- carriageDoor(g, x0): one 4-wide garage bay on the z=7 front (bracing trapdoors on z=6) ------------------------
267	export function carriageDoor(g, x0) {
268	  const z = 7, out = 6;
269	  for (let y = 1; y <= 2; y++) for (let x = x0; x <= x0 + 3; x++) g.set(x, y, z, INTERIOR_WALL);
270	  for (const x of [x0 + 1, x0 + 2]) for (let y = 1; y <= 2; y++) g.set(x, y, out, ...B.trapdoor("dark_oak", "north", "bottom", true));
271	  g.set(x0, 3, z, INTERIOR_WALL); g.set(x0 + 3, 3, z, INTERIOR_WALL);
272	  g.set(x0 + 1, 3, z, GLASS); g.set(x0 + 2, 3, z, GLASS);
273	  for (let x = x0; x <= x0 + 3; x++) put(g, [x, 4, out], B.slab("quartz", "bottom"));
274	}
275	
276	// ---- lampPost(g, x, z): blackstone wall pier y1..3, lantern y4 ------------------------------------------------------
277	export function lampPost(g, x, z) {
278	  g.fill([x, 1, z], [x, 3, z], "blackstone_wall");
279	  g.set(x, 4, z, ...B.lantern(false));
280	}
281	
282	// ---- shrub(g, x, z, { flower }): 3 wide x 1 deep x 2 high azalea on a mulch strip (x-1..x+3, z-1..z+1) ------------
283	export function shrub(g, x, z, { flower = false } = {}) {
284	  for (let dx = -1; dx <= 3; dx++) for (let dz = -1; dz <= 1; dz++) mulchAt(g, x + dx, z + dz);
285	  for (let dx = 0; dx <= 2; dx++) for (let y = 1; y <= 2; y++) g.set(x + dx, y, z, ...leaves(LEAVES));
286	  if (flower) g.set(x + 1, 2, z, ...leaves(FLOWER_LEAVES));
287	}
288	
289	// ---- youngTree(g): oak trunk at (36,1..4,5), crown y4..7, two stakes, mulch ring -----------------------------------
290	export function youngTree(g) {
291	  for (let dx = -1; dx <= 1; dx++) for (let dz = -1; dz <= 1; dz++) mulchAt(g, 36 + dx, 5 + dz);
292	  for (let y = 1; y <= 4; y++) g.set(36, y, 5, ...B.log("oak", "y"));
293	  g.set(35, 1, 5, ...B.fence("oak"));
294	  g.set(37, 1, 5, ...B.fence("oak"));
295	  const layer = (y, r) => {
296	    for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
297	      if (r === 2 && Math.abs(dx) === 2 && Math.abs(dz) === 2) continue;   // the trimmed corners
298	      if (dx === 0 && dz === 0 && y <= 4) continue;                        // the trunk
299	      g.set(36 + dx, y, 5 + dz, ...leaves("oak_leaves"));
300	    }
301	  };
302	  layer(4, 2); layer(5, 2); layer(6, 1);
303	  g.set(36, 7, 5, ...leaves("oak_leaves"));
304	}
305	
306	// ---- deck(g): the back deck, posts, railing, steps, grill, AC unit, back shrub row (plan Part 6) --------------------
307	export function deck(g) {
308	  g.fill([19, 1, 26], [34, 1, 31], DECK_PLANK);
309	  for (let z = 26; z <= 31; z++) g.set(19, 2, z, ...B.fence("spruce"));
310	  for (let x = 19; x <= 34; x++) g.set(x, 2, 31, ...B.fence("spruce"));
311	  for (let z = 26; z <= 31; z++) if (z !== 28 && z !== 29) g.set(34, 2, z, ...B.fence("spruce"));   // gap: the side steps
312	  for (const [x, z] of [[19, 26], [34, 26], [19, 31], [34, 31], [26, 31], [19, 28], [34, 28]])
313	    for (let y = 0; y <= 2; y++) g.set(x, y, z, ...B.log("spruce", "y"));
314	  put(g, [26, 1, 26], B.stairs("spruce", "south", "bottom"));
315	  put(g, [27, 1, 26], B.stairs("spruce", "south", "bottom"));
316	  put(g, [35, 1, 28], B.stairs("spruce", "west", "bottom"));
317	  put(g, [35, 1, 29], B.stairs("spruce", "west", "bottom"));
318	  g.set(31, 2, 28, "cauldron");
319	  put(g, [31, 3, 28], B.trapdoor("iron", "north", "top", false));
320	  for (const x of [36, 37]) for (let y = 1; y <= 2; y++) g.set(x, y, 26, "iron_bars");
321	  for (let x = 3; x <= 13; x += 2) {
322	    g.set(x, 0, 25, MULCH);
323	    g.set(x, 1, 25, ...leaves(LEAVES));
324	  }
325	}
326	
327	// ---- chimney(g): stone shaft x39..41 z25..26, y1..14: base, shoulders, andesite courses, cap and two pots -----------
328	export function chimney(g) {
329	  const { x0, x1, z0, z1 } = CHIMNEY;
330	  g.fill([x0, 1, z0], [x1, 2, z1], "stone_bricks");
331	  g.fill([x0, 3, z0], [x1, 13, z1], "stone_bricks");
332	  for (let x = x0; x <= x1; x++) put(g, [x, 3, z1], B.stairs("stone_brick", "north", "bottom"));
333	  g.fill([x0, 6, z0], [x1, 6, z1], "andesite");
334	  g.fill([x0, 10, z0], [x1, 10, z1], "andesite");
335	  for (let x = x0; x <= x1; x++) for (let z = z0; z <= z1; z++) put(g, [x, 14, z], B.slab("stone_brick", "top"));
336	  g.set(39, 14, 25, "stone_brick_wall");
337	  g.set(41, 14, 25, "stone_brick_wall");
338	}
339	
340	// ---- roofSpec(g): the five roofs in plan order (chimney last); the vent and its frame sit on the entry gable ------
341	export function roofSpec(g) {
342	  roof(g, [[22, 7, 31, 18]], "gable", { y: ROOF_BASE_Y, pitch: 1.0, maxHeight: 5, ridgeAxis: "z", overhang: 1,
343	    eave: "cornice", material: ROOF_MATERIAL, gable: SIDING, verge: "quartz" });
344	  for (let x = 26; x <= 27; x++) for (let y = 11; y <= 12; y++) g.set(x, y, 7, GLASS);
345	  for (const [x, y] of [[25, 11], [25, 12], [28, 11], [28, 12], [26, 10], [27, 10], [26, 13], [27, 13]]) g.set(x, y, 7, TRIM);
346	  roof(g, [[18, 11, 35, 25]], "hip", { y: ROOF_BASE_Y, pitch: 0.55, maxHeight: 4, overhang: 1, eave: "cornice",
347	    ridge: "slab", material: ROOF_MATERIAL, dormers: { face: ["south", "north"], count: 1, style: "gable" } });
348	  roof(g, [[35, 12, 42, 24]], "hip", { y: ROOF_BASE_Y, pitch: 0.5, maxHeight: 3, overhang: 1, eave: "cornice",
349	    ridge: "slab", material: ROOF_MATERIAL, dormers: { face: "north", count: 1, style: "gable" } });
350	  roof(g, [[1, 7, 17, 24]], "hip", { y: ROOF_BASE_Y, pitch: 0.5, maxHeight: 3, overhang: 1, eave: "cornice",
351	    ridge: "slab", material: ROOF_MATERIAL, dormers: { face: "north", count: 2, style: "gable" } });
352	  roof(g, [[38, 8, 42, 12]], "tower-cap", { y: ROOF_BASE_Y, material: ROOF_MATERIAL, finial: "lightning_rod" });
353	  chimney(g);
354	}
